def resolve(path, cwd, links):
    if path is None or cwd is None or links is None:
        return None

    # Start with the current working directory or the path itself
    if path.startswith('/'):
        current = '/'
        components = [c for c in path.split('/') if c and c != '.']
    else:
        current = cwd
        components = [c for c in path.split('/') if c and c != '.']

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent directory
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component to current path
            if current == '/':
                next_path = '/' + component
            else:
                next_path = current + '/' + component

            # Check if this path is a symlink
            if next_path in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[next_path]

                # Get remaining components to process after the link
                remaining = components[i + 1:]

                # Parse the target
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    new_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative symlink target - relative to the directory containing the link
                    current = next_path.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                    new_components = [c for c in target.split('/') if c and c != '.']

                # Replace components with link target components + remaining
                components = new_components + remaining
                i = 0
                continue
            else:
                current = next_path

        i += 1

    # Return result without trailing slash, except for '/'
    if current == '/':
        return '/'
    else:
        return current

